SELECT id, task_id, response_user_id, response_user_name, response_user_department_id,
       response_user_department_name, response_coop_user_id, response_coop_user_name,
       response_time, response_msg_seqid, response_id
FROM tb_static_task_response
WHERE response_time >= #{startTime} AND response_time < #{endTime}

    AND response_user_department_id IN

        #{deptId}



    AND (response_time < #{lastTime} OR (response_time = #{lastTime} AND id < #{lastId}))

ORDER BY response_time DESC, id DESC
LIMIT #{pageSize}
